const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry - equatorial Pacific around 140°W
  const region = ee.Geometry.Rectangle([-142, -2, -138, 2]);

  // 2. Data Acquisition - SeaWiFS chlorophyll data
  const col1998 = ee.ImageCollection('NASA/OCEANDATA/SeaWiFS/L3SMI')
    .filterBounds(region)
    .filterDate('1998-08-01', '1998-08-31')
    .select('chlor_a');

  const col1999 = ee.ImageCollection('NASA/OCEANDATA/SeaWiFS/L3SMI')
    .filterBounds(region)
    .filterDate('1999-12-01', '1999-12-31')
    .select('chlor_a');

  const size1998 = col1998.size().getInfo();
  const size1999 = col1999.size().getInfo();

  console.log(`Aug 1998 Images: ${size1998}`);
  console.log(`Dec 1999 Images: ${size1999}`);

  if (size1998 === 0 || size1999 === 0) {
    console.log('Missing data for one or both periods.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Create composite images (mean)
  const img1998 = col1998.mean();
  const img1999 = col1999.mean();

  // 4. Check pixel counts
  const count1998 = img1998.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  const count1999 = img1999.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  console.log(`Aug 1998 Valid Pixels: ${count1998}`);
  console.log(`Dec 1999 Valid Pixels: ${count1999}`);

  if (count1998 === 0 || count1999 === 0) {
    console.log('No valid pixels after processing.');
    console.log('<answer>C2</answer>');
    return;
  }

  // 5. Calculate mean chlorophyll
  const chlor1998 = img1998.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  const chlor1999 = img1999.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: region,
    scale: 5000,
    maxPixels: 1e9
  }).get('chlor_a').getInfo();

  console.log(`Aug 1998 Chlorophyll: ${chlor1998 !== null ? chlor1998.toFixed(4) : 'null'} mg/m³`);
  console.log(`Dec 1999 Chlorophyll: ${chlor1999 !== null ? chlor1999.toFixed(4) : 'null'} mg/m³`);

  // 6. Validation and answer
  if (chlor1998 === null || chlor1999 === null || 
      isNaN(chlor1998) || isNaN(chlor1999) ||
      chlor1998 < 0 || chlor1999 < 0) {
    console.log('Invalid calculation result.');
    console.log('<answer>C3</answer>');
    return;
  }

  const decrease = chlor1998 - chlor1999;
  console.log(`Change: ${decrease.toFixed(4)} mg/m³`);

  if (chlor1998 > chlor1999) {
    console.log('Chlorophyll decreased from Aug 1998 to Dec 1999.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Chlorophyll did not decrease.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
